def _pair(x):
    return [x[0], x[1]]


def build(n, title, sub, label, why, vocab, balloons, cover, cover_sub, cover_say, recap, teaser,
          cast, lines, quiz, rdg, dictate, produce, rs, sc, names, stage, obra, gancho, hot, gap, trap,
          sticker, speakers, rule, mission_ic, exp, exp_scene, lab, hunt, verbs, vb_title, vb_tip,
          mold, speak, mtrap, mgap, expq, missions, cx):
    B = dict(
        title=title, sub=sub, pattern_label=label, why=why,
        vocab=[[w, pt, 'Soa como “%s”.' % s] for w, pt, s in vocab],
        balloons=[list(b) for b in balloons],
        cover_art=dict(s=cover[0], items=[[e, x, y, z, 'bob'] for e, x, y, z in cover[1]], seed=cover[2]),
        cover_sub=cover_sub, cover_say=cover_say,
        wrap_recap=[list(r) for r in recap], teaser=dict(t=teaser[0], d=teaser[1]),
        cast={k: [v[0], v[1]] for k, v in cast.items()},
        lines=[list(l) for l in lines],
        quiz=[dict(q=q, pt=pt, opts=[list(o) for o in op], a=a, line=ln, why=w) for q, pt, op, a, ln, w in quiz],
        rdg_q=dict(q=rdg[0], o=rdg[1], a=rdg[2], why=rdg[3]),
        dictate=[list(d) for d in dictate],
        produce=dict(prompt=produce[0], ph=produce[1], chips=produce[2], model=produce[3], check=produce[4],
                     kw=produce[5], tips=produce[6], ok=produce[7], reply=produce[8]),
        rs=rs, sc=sc)
    X = dict(
        n=n, review=True, names=list(names), stage=dict(rs=stage[0], chars=[list(c) for c in stage[1]]),
        obra=dict(name=obra[0], kind=obra[1], year=obra[2], text=obra[3], line=[obra[4], obra[5]],
                  pa=dict(t=obra[6], e=obra[7], p=obra[8], v=obra[9])),
        gancho=list(gancho),
        hot=[dict(e=e, x=x, y=y, en=en, pt=pt, say=s, sayPt=sp) for e, x, y, en, pt, s, sp in hot],
        gap=[dict(q=q, pt=pt, opts=o, a=a, why=w) for q, pt, o, a, w in gap],
        trap=[dict(q='Qual frase está certa?', opts=o, a=a, why=w) for o, a, w in trap],
        sticker=dict(title=sticker[0], sub=sticker[1], rs=sticker[2], chars=[list(c) for c in sticker[3]]),
        speakers=speakers, rule=rule, mission_ic=mission_ic)
    XT = dict(
        exp=[dict(ic=ic, en=en, tag=tag, pt=pt, use=use, ex=[xe, xp]) for ic, en, tag, pt, use, xe, xp in exp],
        exp_scene=dict(rs=exp_scene[0], lines=[list(l) for l in exp_scene[1]]),
        lab=dict(short=lab[0], title=lab[1], say=lab[2], intro=dict(what=lab[3], how=lab[4], pt=lab[5]),
                 ex=[list(e) for e in lab[6]], pairs=[list(p) for p in lab[7]], tip=lab[8], phrase=list(lab[9]),
                 rounds=[dict(fig='🎧', say=s, ask='Qual palavra você ouviu?', opts=o, a=a, why=w) for s, o, a, w in lab[10]]),
        hunt=[])
    for h in hunt:
        d = dict(fig='🎧', say=h[0], ask=h[1], opts=h[2], a=h[3], why=h[4])
        if len(h) > 5:
            d['pic'] = 1
        XT['hunt'].append(d)
    VB = dict(title=vb_title, tip=vb_tip, items=[
        dict(v=v, ic=ic, pt=pt, f=[['eu', fi], ['ele/ela', fh]], ex=[xe, xp],
             note='**%s** = %s. Com he/she: **%s**.' % (v, pt, s3))
        for v, ic, pt, s3, fi, fh, xe, xp in verbs])
    MR = dict(
        mold=[dict(label=l, slots=[dict(cat=c, opts=[list(o) for o in op]) for c, op in sl], end=[e, e]) for l, sl, e in mold],
        speak=[list(s) for s in speak],
        trap=[dict(ask=a, opts=o, a=i, why=w, say=s) for a, o, i, w, s in mtrap],
        gap=[dict(text=t, pt=pt, opts=o, a=a, why=w, say=s) for t, pt, o, a, w, s in mgap],
        expq=[dict(ask=a, opts=o, a=i, why=w) for a, o, i, w in expq],
        missions=[dict(ic=ic, name=nm, desc=ds, data=dict(prompt=p, ph='Escreva a sua resposta aqui…', chips=ch, model=m,
                  check=ck, kw=kw, tips=tp, ok=ok, reply=rp)) for ic, nm, ds, p, ch, m, ck, kw, tp, ok, rp in missions])
    CX = [dict(text=t, pt=pt, opts=o, a=0) for t, pt, o in cx]
    return dict(B=B, X=X, XT=XT, VB=VB, MR=MR, CX=CX)


def T(*pairs):
    """tips de produce: cada argumento é uma lista de pares [en, pt]"""
    return [list(p) for p in pairs]


